//! The Rust half of the admin-root rotation and device-grant companion vectors
//! (packages/protocol/test-vectors/pq-authority/vectors.json, generated by
//! tools/pq-authority-vectors.ts). Every case must carry the same verdict as TypeScript, and the
//! old root's companion must re-sign byte for byte.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]

use flagship_crypto::HybridSigningKey;
use flagship_crypto::authority_records::{
    DeviceGrant, Rotation, RotationPq, TAG_ADMIN_ROOT_ROTATION_V2, TAG_DEVICE_CAPABILITY_GRANT,
    binding_key_id_hex, canonical_admin_root_rotation_v2, canonical_device_capability_grant,
    verify_admin_root_rotation_pq, verify_device_grant_pq,
};
use flagship_crypto::trust::{
    BindingWire, Envelope, Expectation, PolicyState, Profile, Role, Rollout, TrustError,
    VerifiedBinding, hex, verify_binding,
};
use flagship_protocol::parse::parse_lower_hex;
use serde_json::Value;
use std::path::PathBuf;

fn vectors() -> Value {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../packages/protocol/test-vectors/pq-authority/vectors.json");
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v[k].as_str().unwrap_or("")
}

fn wire(v: &Value) -> BindingWire<'_> {
    BindingWire {
        version: u8::try_from(v["v"].as_u64().unwrap()).unwrap(),
        role: s(v, "role"),
        subject_id: s(v, "subjectId"),
        ed25519_pub_hex: s(v, "ed25519PubHex"),
        mldsa_pub_hex: s(v, "mldsaPubHex"),
        issued_at: v["issuedAt"].as_u64().unwrap(),
        signature_hex: s(v, "signature"),
    }
}

fn verified(v: &Value, name: &Value) -> Option<VerifiedBinding> {
    let w = &v["bindings"][name.as_str()?];
    Some(
        verify_binding(
            &wire(w),
            &Expectation {
                role: Role::parse(s(w, "role")).unwrap(),
                subject_id: s(w, "subjectId"),
                ed25519_pub_hex: s(w, "ed25519PubHex"),
                mldsa_pub_hex: None,
                now: v["now"].as_u64().unwrap(),
                min_issued_at: None,
            },
        )
        .unwrap(),
    )
}

fn policy(p: &Value) -> PolicyState {
    PolicyState {
        profile: if s(p, "profile") == "strict" {
            Profile::Strict
        } else {
            Profile::Compatibility
        },
        rollout: match s(p, "rollout") {
            "enforced" => Rollout::Enforced,
            "retired" => Rollout::Retired,
            "prepared" => Rollout::Prepared,
            "capable" => Rollout::Capable,
            _ => Rollout::Legacy,
        },
    }
}

fn envelope(v: &Value) -> Option<Envelope<'_>> {
    if !v.is_object() || !v["suite"].is_string() || !v["signature"].is_string() {
        return None;
    }
    Some(Envelope {
        suite: s(v, "suite"),
        signature_hex: s(v, "signature"),
    })
}

fn rotation(v: &Value) -> Rotation<'_> {
    let f = &v["rotation"]["fields"];
    Rotation {
        username: s(f, "username"),
        old_admin_root_pub_hex: s(f, "oldAdminRootPubHex"),
        new_admin_root_pub_hex: s(f, "newAdminRootPubHex"),
        issued_at: f["issuedAt"].as_u64().unwrap(),
    }
}

fn grant(f: &Value) -> DeviceGrant<'_> {
    DeviceGrant {
        grant_id: s(f, "grantId"),
        username: s(f, "username"),
        device_id: s(f, "deviceId"),
        device_pub_hex: s(f, "devicePubKeyHex"),
        scopes: f["scopes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap())
            .collect(),
        issued_at: f["issuedAt"].as_u64().unwrap(),
        expires_at: f["expiresAt"].as_u64().unwrap(),
    }
}

fn signer(v: &Value, name: &str) -> HybridSigningKey {
    let sv = v["signers"]
        .as_array()
        .unwrap()
        .iter()
        .find(|x| x["name"] == name)
        .unwrap();
    let ed: [u8; 32] = parse_lower_hex(s(sv, "edSeedHex"), 32, 32)
        .unwrap()
        .try_into()
        .unwrap();
    let ml: [u8; 32] = parse_lower_hex(s(sv, "mldsaSeedHex"), 32, 32)
        .unwrap()
        .try_into()
        .unwrap();
    HybridSigningKey::from_seeds(&ed, &ml).unwrap()
}

#[test]
fn canonical_bytes_match() {
    let v = vectors();
    let nb = &v["bindings"]["newRoot"];
    let kid = binding_key_id_hex(s(nb, "ed25519PubHex"), s(nb, "mldsaPubHex")).unwrap();
    assert_eq!(kid, s(&v["rotation"], "newRootKeyId"));
    let c = canonical_admin_root_rotation_v2(&rotation(&v), &kid).unwrap();
    assert_eq!(
        String::from_utf8(c).unwrap(),
        s(&v["rotation"], "canonical")
    );
    assert_eq!(
        canonical_admin_root_rotation_v2(&rotation(&v), &"AA".repeat(32)),
        Err(TrustError::BindingMalformed)
    );
    for k in ["admin", "member"] {
        let g = &v["grants"][k];
        let c = canonical_device_capability_grant(&grant(&g["fields"])).unwrap();
        assert_eq!(String::from_utf8(c).unwrap(), s(g, "canonical"), "{k}");
    }
}

#[test]
fn companions_resign_byte_for_byte() {
    let v = vectors();
    let msg = s(&v["rotation"], "canonical").as_bytes();
    let sig = signer(&v, "oldRoot")
        .sign_deterministic(TAG_ADMIN_ROOT_ROTATION_V2, msg)
        .unwrap();
    assert_eq!(hex(&sig), s(&v["rotation"]["pq"]["signature"], "signature"));
    let g = &v["grants"]["admin"];
    let sig = signer(&v, "oldRoot")
        .sign_deterministic(TAG_DEVICE_CAPABILITY_GRANT, s(g, "canonical").as_bytes())
        .unwrap();
    assert_eq!(hex(&sig), s(&g["pq"], "signature"));
}

#[test]
fn rotation_cases() {
    let v = vectors();
    let r = rotation(&v);
    for c in v["rotationCases"].as_array().unwrap() {
        let name = s(c, "name");
        let pq = &c["pq"];
        let companion = pq.is_object().then(|| RotationPq {
            signature: envelope(&pq["signature"]),
            new_root_binding: wire(&pq["newRootBinding"]),
        });
        let old = verified(&v, &c["oldRootBinding"]);
        let got = verify_admin_root_rotation_pq(
            &r,
            companion.as_ref(),
            old.as_ref(),
            &policy(&c["policy"]),
            v["now"].as_u64().unwrap(),
        );
        if c["expect"]["ok"] == true {
            let b = got.unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!(
                hex(b.ed25519_pub()),
                s(&v["bindings"]["newRoot"], "ed25519PubHex"),
                "{name}"
            );
        } else {
            assert_eq!(
                got.err().map(TrustError::code),
                Some(s(&c["expect"], "code")),
                "{name}"
            );
        }
    }
}

#[test]
fn grant_cases() {
    let v = vectors();
    for c in v["grantCases"].as_array().unwrap() {
        let name = s(c, "name");
        let signer_pub = s(&v["bindings"][s(c, "signer")], "ed25519PubHex");
        let b = verified(&v, &c["signerBinding"]);
        let got = verify_device_grant_pq(
            &grant(&c["grant"]),
            envelope(&c["pq"]),
            signer_pub,
            b.as_ref(),
            &policy(&c["policy"]),
        );
        if c["expect"]["ok"] == true {
            got.unwrap_or_else(|e| panic!("{name}: {e}"));
        } else {
            assert_eq!(
                got.err().map(TrustError::code),
                Some(s(&c["expect"], "code")),
                "{name}"
            );
        }
    }
}
